"""Thin wrapper around the fastText engine."""
import importlib
import subprocess
import sys
import os


def get_fasttext():
    """Locate and return a usable fasttext module."""
    # 1. Try existing import
    try:
        import fasttext
        return fasttext, "import"
    except ImportError:
        pass

    # 2. Try pip install fasttext-wheel
    try:
        subprocess.check_call([sys.executable, "-m", "pip", "install", "fasttext-wheel"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        import fasttext
        return fasttext, "fasttext-wheel"
    except Exception:
        pass

    # 3. Try native build from repo
    repo_dir = os.path.dirname(os.path.abspath(__file__))
    repo_dir = os.path.join(repo_dir, "repo")
    if os.path.exists(os.path.join(repo_dir, "setup.py")):
        try:
            subprocess.check_call([sys.executable, "-m", "pip", "install", "."], cwd=repo_dir, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            import fasttext
            return fasttext, "native-build"
        except Exception:
            pass

    raise RuntimeError("No fastText engine available. Install fasttext-wheel or build from source.")


def train_model(fasttext_module, input_path, output_path, **kwargs):
    """Train a fastText supervised model."""
    model = fasttext_module.train_supervised(input=input_path, **kwargs)
    model.save_model(output_path)
    return model


def test_model(model, test_path):
    """Test a fastText model and return (N, P@1, R@1)."""
    return model.test(test_path)


def load_model(fasttext_module, model_path):
    """Load a fastText model from disk."""
    return fasttext_module.load_model(model_path)

