def _detect_provenance():
    """Detect how fasttext was installed."""
    try:
        import fasttext
        module_path = os.path.dirname(os.path.abspath(fasttext.__file__))
        # Check if it's a wheel installation
        if "fasttext_wheel" in module_path or "fasttext-wheel" in module_path:
            return "fasttext-wheel"
        # Check if it's a native build from the repo
        if "site-packages" in module_path:
            return "native-build"
        return "unknown"
    except Exception:
        return "unknown"
